/// 🎟️ An interrupted work quote resumes its original granted shared birth without another quote.
#[test]
fn native_shared_interrupted_work_quote_resumes_grant(){
 struct Interrupt{calls:usize}impl crate::native_decoding::OriginalWorkRecipient for Interrupt{fn admits<'a>(&mut self,quote:crate::native_decoding::OriginalWorkQuote<'a>,_:u64,_:u64)->crate::native_decoding::OriginalWorkQuoteComplete<'a>{self.calls+=1;let completed=quote.complete(Ok(true));std::hint::black_box(&completed);panic!("original work quote interrupted after actual reply")}}
 let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut authority=OriginalConstructionAuthority::new(Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0});let mut work_issuer=crate::native_decoding::OriginalWorkActionIssuer::new();let mut work=Interrupt{calls:0};let mut work_loan=work_issuer.loan(&mut work);let mut input=Some(17i64);let mut output=None;let mut owner=NativeSharedAdmission::default();
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut owner)))))));assert!(interrupted.is_err());assert!(owner.can_advance());assert_eq!(input,Some(17));
 let turn=authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|{assert_eq!(control.recover_work_quote()?,Some(true));Ok::<_,ValueError>(control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut owner))}))).unwrap().unwrap();assert!(turn.result.is_ok());assert_eq!(turn.work,SealedShared::<i64>::birth_work_demand());assert!(owner.has_birth());drop(work_loan);assert_eq!(work.calls,1);let demand=owner.close_demand().unwrap();let mut actual=None;assert!(owner.close_step(&mut crate::RetainedAllocationEffect::new(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth,..Default::default()},1,&mut actual)).result.is_ok());
}

