#[test]
fn native_shared_interrupted_post_rebinds_original_work(){use crate::native_decoding::{NativeAllocationEvent,NativeDecodeAllocationIssuer,OriginalWorkActionIssuer};let mut callback=|_|true;let mut port=|event|match event{NativeAllocationEvent::Post{..}=>panic!("original post interrupted"),_=>Ok(())};let mut allocation_issuer=NativeDecodeAllocationIssuer::new();let mut allocation_loan=allocation_issuer.loan(&mut port);let mut control=NativeDecodeControl::new_forwarded(4096,&mut callback,&mut allocation_loan);let mut recipient=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut construction_issuer=NativeConstructionRecipientIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_issuer=OriginalWorkActionIssuer::new();let mut work_backend=ConstructionWork;let mut work_loan=work_issuer.loan(&mut work_backend);let mut input=Some(17i64);let mut output=None;let mut owner=NativeSharedAdmission::default();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(&mut construction_loan,|control|Ok::<_,ValueError>(control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut owner))))));assert!(interrupted.is_err());assert!(control.has_pending_work());assert!(owner.has_birth());assert_eq!(input,Some(17));assert!(output.is_none());let turn=control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(&mut construction_loan,|control|{owner.receiving_effect().resolve_allocation_callback(control,Ok(())).map_err(|(error,_)|error)?;owner.receiving_effect().finish_allocation(control)?;Ok::<_,ValueError>(owner.resume(control))})).unwrap();assert_eq!(turn.work,SealedShared::<i64>::birth_work_demand());assert!(turn.result.is_ok());assert!(!control.has_pending_work());assert!(owner.has_birth());let demand=owner.close_demand().unwrap();assert!({let mut actual=None;owner.close_step(&mut crate::RetainedAllocationEffect::new(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth,..Default::default()},1,&mut actual))}.result.is_ok());}
