/// 🧾️ The original caller retains its input or output across independently refused allocation events.
#[test]
fn native_shared_allocation_quotes_before_effect_and_keeps_born_owner_on_post_refusal(){
 use crate::native_decoding::NativeAllocationEvent;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/effect-frame.json")).unwrap();
 for case in fixture["sharedAdmission"].as_array().unwrap(){let quote=case["id"]=="quote-refused";let events=std::sync::Mutex::new(Vec::new());let mut port=|event|{let name=match event{NativeAllocationEvent::Quote(_)=>"quote",NativeAllocationEvent::Post{..}=>"post",NativeAllocationEvent::Cancel(_)=>"cancel"};events.lock().unwrap().push(name);if (quote&&name=="quote")||(!quote&&name=="post"){Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original allocation callback refused"))}else{Ok(())}};let mut callback=|_|true;let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut control=NativeDecodeControl::new_forwarded(4096,&mut callback,&mut loan);let mut recipient=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut construction_issuer=NativeConstructionRecipientIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut input=Some("original owner".to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut output=None;let mut frame=NativeSharedAdmission::default();let turn=funded(&mut control,|control|control.with_construction_recipient(&mut construction_loan,|control|Ok::<_,ValueError>(control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut frame))).unwrap());assert!(turn.result.is_err());assert_eq!(frame.has_birth(),case["born"].as_bool().unwrap());assert_eq!(output.is_some(),case["output"].as_bool().unwrap());assert_eq!(input.is_some(),case["input"].as_bool().unwrap());if frame.has_birth(){let d=frame.close_demand().unwrap();let turn={let mut actual=None;frame.close_step(&mut crate::RetainedAllocationEffect::new(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..Default::default()},1,&mut actual))};assert!(turn.result.is_ok());assert!(frame.terminal_is_empty())}drop(construction_loan);assert_eq!(recipient.receipts,usize::from(case["receipt"].as_bool().unwrap()));let observed=events.lock().unwrap().clone();assert_eq!(observed,case["events"].as_array().unwrap().iter().map(|v|v.as_str().unwrap()).collect::<Vec<_>>());if let Some(input)=input.take(){assert_eq!(input.as_ptr(),pointer);close(input)}if let Some(output)=output.take(){assert_eq!(output.get().as_ptr(),pointer);close(output)}close(turn.result.unwrap_err());
 }
}
struct Recipient{submitted:RetainedCloneProgress,axis:Option<&'static str>,accept:bool,calls:usize,receipts:usize}
impl OriginalConstructionRecipient for Recipient{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:crate::OriginalConstructionGrant<'a>)->crate::OriginalConstructionGrantComplete<'a>where 'source:'turn{self.calls+=1;let d=quote.demand();let mut g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};match self.axis{Some("items")=>g.maximum_items=0,Some("copy")=>g.maximum_copy_bytes=0,Some("capacity")=>g.maximum_capacity_bytes=0,Some("depth")=>g.maximum_depth=0,_=>{}}quote.complete(Ok(g))}
 fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:crate::OriginalConstructionAccept<'a>)->crate::OriginalConstructionAcceptComplete<'a>where 'source:'turn{let g=receipt.grant();let p=receipt.progress();assert!(p.fits(g));self.receipts+=1;let result=self.submitted.checked_add(p).and_then(|total|{self.submitted=total;if self.accept{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original construction receipt refused"))}});receipt.complete(result)}
 fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}
}

fn close<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("constructed output supports typed closure"));for turn in 0..10000{if owner.terminal_is_empty(){return;}let d=owner.next_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let work=owner.next_computational_work(4096).unwrap();let mut actual=None;let mut effect=crate::RetainedAllocationEffect::new(g,work,&mut actual);let step=owner.step(&mut effect).unwrap();assert!(step.progress().fits(g));assert!(turn<9999);}}
/// 🧫️ Portable refusal and receipt cases conserve original payload identity and born physical custody.
#[test]
fn native_owned_construction_preserves_original_and_born_slots_under_all_admission_axes(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../../🏭️construction/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in corpus.as_array().unwrap(){let id=case["id"].as_str().unwrap();let axis=match id{"denied-items"=>Some("items"),"denied-copy"=>Some("copy"),"denied-capacity"=>Some("capacity"),"denied-depth"=>Some("depth"),_=>None};let mut recipient=Recipient{submitted:Default::default(),axis,accept:case["receiptAccepted"].as_bool().unwrap(),calls:0,receipts:0};let mut issuer=NativeConstructionRecipientIssuer::new();let mut loan=issuer.loan(&mut recipient);let mut input=Some("original owned payload".to_owned());let address=input.as_ref().unwrap().as_ptr();let mut output=None;let mut owner=NativeSharedAdmission::default();let mut callback=|_|true;let mut original=NativeDecodeControl::new(4096,&mut callback);let mut payer=ConstructionWork;let mut payer_issuer=crate::native_decoding::OriginalWorkActionIssuer::new();let mut payer_loan=payer_issuer.loan(&mut payer);let(first,birth_heap)=original.with_work_recipient(&mut payer_loan,|original|{let mut control=NativeOwnedDecodeControl::new(original,&mut loan);
  let(first,birth_heap)=crate::observe_retirement_allocations(||control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut owner));let born=case["birth"].as_bool().unwrap();assert_eq!(owner.has_birth(),born);assert!(output.is_none());assert_eq!(input.as_ref().unwrap().as_ptr(),address);assert_eq!(birth_heap,(if born{SealedShared::<String>::birth_bytes()}else{0},0));assert_eq!(first.result.is_err(),case["failure"].as_bool().unwrap());
  if born&&!case["failure"].as_bool().unwrap(){let(second,heap)=crate::observe_retirement_allocations(||control.receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut owner));assert!(second.result.is_ok());assert_eq!(heap,(0,0));}drop(control);Ok::<_,ValueError>((first,birth_heap))}).unwrap();drop(loan);assert_eq!(recipient.calls,case["calls"].as_u64().unwrap()as usize);assert_eq!(recipient.receipts,case["receipts"].as_u64().unwrap()as usize);assert_eq!(output.is_some(),case["publication"].as_bool().unwrap());assert_eq!(original.owned_bytes(),birth_heap.0);
  if owner.has_birth(){let demand=owner.close_demand().unwrap();let(turn,heap)=crate::observe_retirement_allocations(||{let mut actual=None;owner.close_step(&mut crate::RetainedAllocationEffect::new(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth,..Default::default()},1,&mut actual))});assert!(turn.result.is_ok());assert_eq!(heap,(0,birth_heap.0));}assert!(owner.terminal_is_empty());if let Some(value)=input.take(){assert_eq!(value.as_ptr(),address);close(value)}if let Some(value)=output.take(){assert_eq!(value.get().as_ptr(),address);close(value)}if let Err(error)=first.result{assert_eq!(error.retained_progress().retained_capacity_bytes,birth_heap.0);close(error)}
 }
}
