/// 🔗️ Scoped observers and typed retirement children keep the same original construction port and cumulative ledger.
#[test]
fn native_owned_construction_scoped_children_preserve_original_grant_recipient(){
 let mut recipient=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut foreign=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut construction_issuer=NativeConstructionRecipientIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut foreign_issuer=NativeConstructionRecipientIssuer::new();let mut foreign_loan=foreign_issuer.loan(&mut foreign);let mut frame=NativeSharedAdmission::default();let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let ledger=control.ledger_identity();let mut original_retirement=crate::NativeDecodeRetirementRecipient::new();control.install_retirement_recipient(&mut original_retirement).unwrap();let mut child_retirement=crate::NativeDecodeRetirementRecipient::new();let mut first=Some(7i64);let mut second=Some(9i64);let mut out_first=None;let mut out_second=None;
 funded(&mut control,|control|control.with_construction_recipient(&mut construction_loan,|control|->Result<(),OriginalReceivingPrimary>{assert_eq!(control.ledger_identity(),ledger);let mut observer=|_|true;control.scoped_observer(&mut observer,|control|{assert_eq!(control.ledger_identity(),ledger);control.receive_shared(&mut first,&mut out_first,SharedIssuer::owned(),&mut frame).result?;control.receive_shared(&mut first,&mut out_first,SharedIssuer::owned(),&mut frame).result.map(|_|())})?;control.with_retirement_owner(0,|control|{let result=control.with_retirement_child(&mut child_retirement,|child|{assert_eq!(child.ledger_identity(),ledger);child.receive_shared(&mut second,&mut out_second,SharedIssuer::owned(),&mut frame).result?;child.receive_shared(&mut second,&mut out_second,SharedIssuer::owned(),&mut frame).result.map(|_|())});(result,None)})?;assert!(control.with_construction_recipient(&mut foreign_loan,|_|Ok::<_,ValueError>(())).is_err());Ok(())}).unwrap());drop(construction_loan);drop(foreign_loan);assert_eq!((recipient.calls,recipient.receipts),(4,4));assert_eq!((foreign.calls,foreign.receipts),(0,0));assert_eq!(control.owned_bytes(),SealedShared::<i64>::birth_bytes()*2);assert_eq!(*out_first.as_ref().unwrap().get(),7);assert_eq!(*out_second.as_ref().unwrap().get(),9);let mut plain_input=Some(11i64);let mut plain_output=None;assert!(control.receive_shared(&mut plain_input,&mut plain_output,SharedIssuer::owned(),&mut frame).result.is_err());assert_eq!(plain_input,Some(11));assert!(plain_output.is_none());close(out_first.take().unwrap());close(out_second.take().unwrap());
}

/// 🪢️ The actual typed receiver preserves output or semantic error on a simultaneous recipient refusal.
#[test]
fn native_construction_typed_result_preserves_original_owners_on_receipt_refusal(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../../🏭️construction/🧾️result/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){
  let admitted=row["admitted"].as_bool().unwrap();let fail=row["primary"].as_bool().unwrap();let recipient=Recipient{submitted:Default::default(),axis:if admitted{None}else{Some("items")},accept:row["accept"].as_bool().unwrap(),calls:0,receipts:0};
  let mut input=Some("original typed payload 源".to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut primary=Some(ValueError::new(ValueRefusalKind::InvalidValue,"original typed primary 拒"));let primary_pointer=primary.as_ref().unwrap().message.as_ptr();let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut calls=0;
  let mut authority=OriginalConstructionAuthority::new(recipient);let(outcome,heap)=crate::observe_retirement_allocations(||authority.with_loan(&mut (),|construction_loan|control.with_construction_recipient(construction_loan,|control|Ok::<_,ValueError>(control.receive_construction_step_typed(RetirementDemand{depth:1,..Default::default()},|_,_|{calls+=1;NativeConstructionStepResult { result:if fail{Err(primary.take().unwrap())}else{Ok(input.take().unwrap())},progress:RetainedCloneProgress{copied_items:1,..Default::default()},work:1 }})))).unwrap().unwrap());
  assert_eq!(heap,(0,0));assert_eq!(calls,usize::from(admitted));assert_eq!(authority.inspect(|recipient|recipient.receipts),usize::from(admitted));assert_eq!(outcome.receipt_refusal.is_some(),row["receipt"].as_bool().unwrap());assert_eq!(outcome.progress.copied_items,usize::from(admitted));assert_eq!(outcome.work,u64::from(admitted));
  match outcome.result { Some(Ok(value))=>{assert_eq!(value.as_ptr(),pointer);close(value)},Some(Err(error))=>{assert_eq!(error.message.as_ptr(),primary_pointer);close(error)},None=>assert!(!admitted) }
  if let Some(error)=outcome.receipt_refusal {assert_eq!(error.retained_progress(),outcome.progress);close(error)}
  if let Some(value)=input.take(){assert_eq!(value.as_ptr(),pointer);close(value)}if let Some(error)=primary.take(){close(error)}
 }
}

