/// 🪪️ Grant and receipt unwind retain the child work and require the exact original recipient.
#[test]
fn native_effect_callback_unwind_requires_original_recipient_and_preserves_work(){
 use crate::native_decoding::construction::{NativeReceivingEffect,NativeReceivingEffectPhase};
 struct Interrupted{grant:bool,receipt:bool,refusal:Option<ValueError>}
 impl OriginalConstructionRecipient for Interrupted{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:crate::OriginalConstructionGrant<'a>)->crate::OriginalConstructionGrantComplete<'a>where 'source:'turn{assert!(self.grant);self.grant=false;let completed=quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}));std::hint::black_box(&completed);panic!("grant producer interrupted after reply")}fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:crate::OriginalConstructionAccept<'a>)->crate::OriginalConstructionAcceptComplete<'a>where 'source:'turn{assert!(self.receipt);self.receipt=false;let completed=receipt.complete(Err(self.refusal.take().unwrap()));std::hint::black_box(&completed);panic!("receipt producer interrupted after reply")}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{Default::default()}}
 let refusal=ValueError::new(ValueRefusalKind::OwnershipLimit,"receipt refusal remains owned");let pointer=refusal.message.as_ptr();let mut authority=OriginalConstructionAuthority::new(Interrupted{grant:true,receipt:true,refusal:Some(refusal)});let mut foreign=OriginalConstructionAuthority::new(Interrupted{grant:false,receipt:false,refusal:None});let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut payer=ConstructionWork;let mut work_issuer=crate::native_decoding::OriginalWorkActionIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);let mut frame=NativeReceivingEffect::<ValueError>::default();let demand=RetirementDemand{depth:1,..Default::default()};
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|frame.quote(control,demand))))));assert!(interrupted.is_err());assert_eq!(frame.phase(),NativeReceivingEffectPhase::GrantStarted);let wrong=foreign.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|frame.recover_grant(control)))).unwrap();assert!(wrong.is_err());authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|{assert_eq!(frame.recover_grant(control)?,true);{assert_eq!(frame.prepare_work(control,3)?,Some(true));frame.effect(control,|actual,_|{*actual=Some(0);crate::RetainedWorkOutcome{result:Ok(crate::RetainedCloneStep::Progress(Default::default())),work:3}})?;frame.settle_original_work(control,3)?;frame.finish_allocation(control)?;Ok::<_,ValueError>(())}}))).unwrap().unwrap();
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|frame.receipt(control))))));assert!(interrupted.is_err());assert_eq!(frame.phase(),NativeReceivingEffectPhase::ReceiptStarted);let wrong=foreign.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|frame.recover_receipt(control)))).unwrap();assert!(wrong.is_err());let turn=authority.with_loan(&mut (),|loan|control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(loan,|control|{assert_eq!(frame.recover_receipt(control)?,true);frame.take(control)}))).unwrap().unwrap();assert_eq!(turn.work,3);let failure=turn.result.unwrap_err();assert_eq!(failure.receiving.receipt_refusal.as_ref().unwrap().message.as_ptr(),pointer);close(failure);
}

