/// 🧳️ A panicking child progress accessor cannot discard the original error or work.
#[test]
fn native_effect_retains_child_when_progress_accessor_unwinds(){
 use crate::native_decoding::construction::{NativeReceivingEffect,NativeReceivingEffectError};use std::sync::atomic::{AtomicBool,Ordering};struct Error{first:AtomicBool,inner:ValueError}
 impl RetireOwned for Error{type RetirementCursor=<ValueError as RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{self.inner.retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{self.inner.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
 impl NativeReceivingEffectError for Error{fn receiving_progress(&self)->RetainedCloneProgress{if self.first.swap(false,Ordering::SeqCst){panic!("child progress interrupted")}self.inner.retained_progress()}}
 let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut recipient=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut construction_issuer=NativeConstructionRecipientIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut frame=NativeReceivingEffect::<Error>::default();let error=ValueError::new(ValueRefusalKind::InvalidValue,"original child owner");let pointer=error.message.as_ptr();let mut original=Some(Error{first:AtomicBool::new(true),inner:error});let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.with_construction_recipient(&mut construction_loan,|control|{frame.quote(control,RetirementDemand{depth:1,..Default::default()})?;frame.effect(control,|actual,_|{*actual=Some(0);crate::RetainedWorkOutcome{result:Err(original.take().unwrap()),work:9}})})));assert!(interrupted.is_err());let turn=control.with_construction_recipient(&mut construction_loan,|control|{frame.finish_allocation(control)?;frame.receipt(control)?;frame.take(control)}).unwrap();assert_eq!(turn.work,9);let failure=match turn.result{Err(failure)=>failure,Ok(_)=>panic!("original child error disappeared")};assert_eq!(failure.child.as_ref().unwrap().inner.message.as_ptr(),pointer);close(failure);close(frame);
}

