#[test]
fn native_arc_birth_is_fallible_and_publishes_only_after_birth(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🏭️construction/🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let row=&fixture["arcBirth"];let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut authority=OriginalConstructionAuthority::new(Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0});let mut input=Some(row["published"].as_i64().unwrap());let mut output=None;let mut owner=NativeSharedAdmission::default();let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||funded(&mut control,|control|authority.with_loan(&mut (),|loan|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(control.receive_arc(&mut input,&mut output,&mut owner)))).unwrap().unwrap())));assert_eq!(attempts,row["nullAttempts"].as_u64().unwrap()as usize);assert_eq!(heap,(0,0));assert!(turn.result.is_err());assert!(input.is_some()&&output.is_none()&&!owner.has_birth());close(turn.result.unwrap_err());let(turn,heap)=crate::observe_retirement_allocations(||funded(&mut control,|control|authority.with_loan(&mut (),|loan|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(control.receive_arc(&mut input,&mut output,&mut owner)))).unwrap().unwrap()));assert!(turn.result.is_ok());assert_eq!(heap,(NativeOwnedDecodeControl::arc_birth_demand::<i64>().capacity_bytes,0));assert!(owner.has_birth()&&input.is_some()&&output.is_none());let(turn,heap)=crate::observe_retirement_allocations(||funded(&mut control,|control|authority.with_loan(&mut (),|loan|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(control.receive_arc(&mut input,&mut output,&mut owner)))).unwrap().unwrap()));assert!(turn.result.is_ok());assert_eq!(heap,(0,0));assert!(owner.terminal_is_empty()&&input.is_none());assert_eq!(**output.as_ref().unwrap(),row["published"].as_i64().unwrap());assert_eq!(authority.inspect(|recipient|recipient.receipts),row["receipts"].as_u64().unwrap()as usize);close(output.take().unwrap());
}

/// 🪪️ Distinct pending actions retain one source issuer until their own original handoffs.
#[test]
fn native_effect_issuer_counts_multiple_actions_and_rejects_foreign_handoff(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🏭️construction/🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let row=&fixture["multiActions"];let mut callback=|_|true;let mut control=NativeDecodeControl::new(0,&mut callback);let mut recipient=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut issuer=NativeConstructionRecipientIssuer::new();let mut first=NativeReceivingEffect::<ValueError>::default();let mut second=NativeReceivingEffect::<ValueError>::default();{let mut loan=issuer.loan(&mut recipient);control.with_construction_recipient(&mut loan,|control|{first.quote(control,RetirementDemand{depth:1,..Default::default()})?;second.quote(control,RetirementDemand{depth:1,..Default::default()})?;first.effect(control,|actual,_|{*actual=Some(0);crate::RetainedWorkOutcome{result:Ok(crate::RetainedCloneStep::Progress(Default::default())),work:0}})?;first.receipt(control)}).unwrap();}assert_eq!(issuer.outstanding(),row["initial"].as_u64().unwrap()as usize);let mut foreign=Recipient{submitted:Default::default(),axis:None,accept:true,calls:0,receipts:0};let mut foreign_issuer=NativeConstructionRecipientIssuer::new();{let mut foreign_loan=foreign_issuer.loan(&mut foreign);let refused=control.with_construction_recipient(&mut foreign_loan,|control|Ok::<_,ValueError>(first.take(control))).unwrap();assert_eq!(refused.is_err(),row["wrongTakeRejected"].as_bool().unwrap());}{let mut loan=issuer.loan(&mut recipient);let turn=control.with_construction_recipient(&mut loan,|control|first.take(control)).unwrap();assert!(turn.result.is_ok());}assert_eq!(issuer.outstanding(),row["afterFirst"].as_u64().unwrap()as usize);{let mut loan=issuer.loan(&mut recipient);let turn=control.with_construction_recipient(&mut loan,|control|{second.effect(control,|actual,_|{*actual=Some(0);crate::RetainedWorkOutcome{result:Ok(crate::RetainedCloneStep::Progress(Default::default())),work:0}})?;second.receipt(control)?;second.take(control)}).unwrap();assert!(turn.result.is_ok());}assert_eq!(issuer.outstanding(),row["afterSecond"].as_u64().unwrap()as usize);close(first);close(second);
}
